.emoji-picker {
    position: absolute;
    top: -4px;
    right: 140px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 4px;
    display: flex;
    gap: 2px;
    box-shadow: 0 2px 8px rgba(0,0,0,.15);
    z-index: 3;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    line-height: 1;
}

    .emoji-option:hover {
        background: #f0f0f0;
    }

/* Message input */

.message-input-area,
.thread-input-area {
    padding: 12px 20px;
    border-top: 1px solid #e8e8e8;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-input {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 12px;
    font-size: .9rem;
    font-family: inherit;
    outline: none;
    transition: border-color .15s;
}

    .message-input:focus {
        border-color: #1264a3;
    }

.send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 18px;
    font-size: .9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background .15s;
    white-space: nowrap;
}

    .send-btn:hover:not(:disabled) {
        background: #005e44;
    }

    .send-btn:disabled {
        opacity: .5;
        cursor: default;
    }

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #888;
    font-size: 1.1rem;
}

/* ── Thread panel ───────────────────────── */

.thread-panel {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    display: flex;
    flex-direction: column;
    background: #fff;
    border-left: 1px solid #e8e8e8;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

    .thread-header h5 {
        margin: 0;
        font-size: 1rem;
    }

.close-thread-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #666;
    padding: 2px 6px;
    border-radius: 4px;
}

    .close-thread-btn:hover {
        background: #f0f0f0;
    }

