    padding: 12px 16px;
    background: #f8f8f8;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

    .thread-root-quote p {
        margin: 4px 0 0;
        font-size: .9rem;
    }

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
}

.thread-reply {
    padding: 6px 0;
    border-bottom: 1px solid #f0f0f0;
}

    .thread-reply:last-child {
        border-bottom: none;
    }

