    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: #1d1c1d;
    background: #fff;
}

/* ── Sidebar ────────────────────────────── */

.channel-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    background: #3f0e40;
    color: #cfc3cf;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid rgba(255,255,255,.1);
}

    .sidebar-header h5 {
        color: #fff;
        margin: 0;
        font-size: 1.1rem;
    }

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 6px 16px;
    cursor: pointer;
    position: relative;
    border-radius: 6px;
    margin: 0 8px;
    transition: background .15s;
}

    .channel-item:hover {
        background: rgba(255,255,255,.1);
    }

    .channel-item.active {
        background: #1264a3;
        color: #fff;
    }

.channel-name {
    font-weight: 600;
    font-size: .95rem;
}

.channel-desc {
    font-size: .75rem;
    opacity: .7;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #e01e5a;
    color: #fff;
    font-size: .7rem;
    font-weight: 700;
    border-radius: 10px;
    padding: 1px 7px;
    min-width: 18px;
    text-align: center;
}

/* ── Main message area ──────────────────── */

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border-right: 1px solid #e8e8e8;
}

    .message-area.with-thread {
        max-width: 55%;
    }

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

    .message-header h4 {
        margin: 0 0 2px;
        font-size: 1.1rem;
    }

.channel-description {
    font-size: .85rem;
    color: #616061;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

.loading-indicator {
    text-align: center;
    color: #888;
    padding: 8px;
    font-size: .85rem;
}

.message-row {
    position: relative;
    padding: 6px 8px;
    border-radius: 6px;
    transition: background .1s;
}

    .message-row:hover {
        background: #f8f8f8;
    }

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.author {
    font-size: .95rem;
}

.timestamp {
    font-size: .75rem;
    color: #888;
}

.message-text {
    margin: 2px 0 4px;
    font-size: .93rem;
    line-height: 1.45;
    white-space: pre-wrap;
    word-break: break-word;
}

/* Reactions */

.reaction-row {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    margin-top: 2px;
}

.reaction-badge {
    background: #f0f0f0;
    border: 1px solid #ddd;
    border-radius: 12px;
    padding: 1px 8px;
    font-size: .8rem;
    cursor: pointer;
    transition: background .15s;
}

    .reaction-badge:hover {
        background: #e0e0ff;
        border-color: #aac;
    }

/* Thread link */

.thread-link {
    background: none;
    border: none;
    color: #1264a3;
    font-size: .82rem;
    cursor: pointer;
    padding: 2px 0;
    font-weight: 600;
}

    .thread-link:hover {
        text-decoration: underline;
    }

/* Hover action buttons */

.message-actions {
    position: absolute;
    top: -4px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 1px 4px rgba(0,0,0,.12);
    z-index: 2;
}

.action-btn {
    background: none;
    border: none;
    padding: 4px 8px;
    font-size: .8rem;
    cursor: pointer;
    border-radius: 4px;
    white-space: nowrap;
}

    .action-btn:hover {
        background: #f0f0f0;
    }

/* Emoji picker */

.emoji-picker {
    position: absolute;
    top: -4px;
    right: 140px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 4px;
    display: flex;
    gap: 2px;
    box-shadow: 0 2px 8px rgba(0,0,0,.15);
    z-index: 3;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    line-height: 1;
}

    .emoji-option:hover {
        background: #f0f0f0;
    }

/* Message input */

.message-input-area,
.thread-input-area {
    padding: 12px 20px;
    border-top: 1px solid #e8e8e8;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-input {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 12px;
    font-size: .9rem;
    font-family: inherit;
    outline: none;
    transition: border-color .15s;
}

    .message-input:focus {
        border-color: #1264a3;
    }

.send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 18px;
    font-size: .9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background .15s;
    white-space: nowrap;
}

    .send-btn:hover:not(:disabled) {
        background: #005e44;
    }

    .send-btn:disabled {
        opacity: .5;
        cursor: default;
    }

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #888;
    font-size: 1.1rem;
}

/* ── Thread panel ───────────────────────── */

.thread-panel {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    display: flex;
    flex-direction: column;
    background: #fff;
    border-left: 1px solid #e8e8e8;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

    .thread-header h5 {
        margin: 0;
        font-size: 1rem;
    }

.close-thread-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #666;
    padding: 2px 6px;
    border-radius: 4px;
}

    .close-thread-btn:hover {
        background: #f0f0f0;
    }

.thread-root-quote {
    padding: 12px 16px;
    background: #f8f8f8;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

    .thread-root-quote p {
        margin: 4px 0 0;
        font-size: .9rem;
    }

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
}

.thread-reply {
    padding: 6px 0;
    border-bottom: 1px solid #f0f0f0;
}

    .thread-reply:last-child {
        border-bottom: none;
    }
