/* ═══════════════════════════════════════════
   Chat page – scoped styles
   ═══════════════════════════════════════════ */

.chat-container {
    display: flex;
    height: 100vh;
    width: 100vw;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: #1d1c1d;
    background: #fff;
}

/* ── Sidebar ────────────────────────────── */

.channel-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    background: #3f0e40;
    color: #cfc3cf;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid rgba(255,255,255,.1);
}

    .sidebar-header h5 {
        color: #fff;
        margin: 0;
        font-size: 1.1rem;
    }

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 6px 16px;
    cursor: pointer;
    position: relative;
    border-radius: 6px;
    margin: 0 8px;
    transition: background .15s;
}

    .channel-item:hover {
        background: rgba(255,255,255,.1);
    }

    .channel-item.active {
        background: #1264a3;
        color: #fff;
    }

.channel-name {
    font-weight: 600;
